{
  "author": "Isaac Z. Schlueter <i@izs.me> (https://blog.izs.me/)",
  "name": "glob",
  "description": "the most correct and second fastest glob implementation in JavaScript",
  "version": "13.0.6",
  "type": "module",
  "tshy": {
    "selfLink": false,
    "exports": {
      "./package.json": "./package.json",
      "./raw": "./src/index.ts",
      ".": {
        "import": {
          "types": "./dist/esm/index.d.ts",
          "default": "./dist/esm/index.min.js"
        },
        "require": {
          "types": "./dist/commonjs/index.d.ts",
          "default": "./dist/commonjs/index.min.js"
        }
      }
    }
  },
  "main": "./dist/commonjs/index.min.js",
  "module": "./dist/esm/index.min.js",
  "types": "./dist/commonjs/index.d.ts",
  "exports": {
    "./package.json": "./package.json",
    "./raw": {
      "import": {
        "types": "./dist/esm/index.d.ts",
        "default": "./dist/esm/index.js"
      },
      "require": {
        "types": "./dist/commonjs/index.d.ts",
        "default": "./dist/commonjs/index.js"
      }
    },
    ".": {
      "import": {
        "types": "./dist/esm/index.d.ts",
        "default": "./dist/esm/index.min.js"
      },
      "require": {
        "types": "./dist/commonjs/index.d.ts",
        "default": "./dist/commonjs/index.min.js"
      }
    }
  },
  "repository": {
    "type": "git",
    "url": "git@github.com:isaacs/node-glob.git"
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "preversion": "npm test",
    "postversion": "npm publish",
    "prepublishOnly": "npm run benchclean; git push origin --follow-tags",
    "prepare": "tshy && bash scripts/build.sh",
    "pretest": "npm run prepare",
    "presnap": "npm run prepare",
    "test": "tap",
    "snap": "tap",
    "posttest": "npm run lint",
    "postsnap": "npm run lint",
    "format": "prettier --write .",
    "lint": "oxlint --fix src test",
    "postlint": "npm run format",
    "typedoc": "typedoc",
    "profclean": "rm -f v8.log profile.txt",
    "test-regen": "npm run profclean && TEST_REGEN=1 node --no-warnings --loader ts-node/esm test/00-setup.ts",
    "prebench": "npm run prepare",
    "bench": "bash benchmark.sh",
    "preprof": "npm run prepare",
    "prof": "bash prof.sh",
    "benchclean": "node benchclean.cjs"
  },
  "dependencies": {
    "minimatch": "^10.2.4",
    "minipass": "^7.1.3",
    "path-scurry": "^2.0.2"
  },
  "devDependencies": {
    "@types/node": "^25.6.0",
    "esbuild": "^0.28.0",
    "memfs": "^4.50.0",
    "mkdirp": "^3.0.1",
    "oxlint": "^1.62.0",
    "oxlint-tsgolint": "^0.22.1",
    "prettier": "^3.8.3",
    "rimraf": "^6.1.3",
    "tap": "^21.7.1",
    "tshy": "^4.1.1",
    "typedoc": "^0.28.19"
  },
  "license": "BlueOak-1.0.0",
  "funding": {
    "url": "https://github.com/sponsors/isaacs"
  },
  "engines": {
    "node": "18 || 20 || >=22"
  },
  "allowScripts": {
    "esbuild@0.28.0": true
  }
}

