{
  "name": "glob-bin",
  "version": "1.1.0",
  "description": "the command line bin script that used to be in node-glob",
  "author": "Isaac Z. Schlueter <i@izs.me> (https://blog.izs.me)",
  "files": [
    "dist"
  ],
  "bin": {
    "glob-bin": "dist/esm/bin-min.mjs",
    "glob": "dist/esm/bin-min.mjs"
  },
  "license": "BlueOak-1.0.0",
  "scripts": {
    "preversion": "npm test",
    "postversion": "npm publish",
    "prepublishOnly": "git push origin --follow-tags",
    "prepare": "tshy && bash scripts/build.sh",
    "pretest": "npm run prepare",
    "presnap": "npm run prepare",
    "test": "tap",
    "snap": "tap",
    "format": "prettier --write . --log-level warn",
    "typedoc": "typedoc",
    "lint": "oxlint --fix src test",
    "postsnap": "npm run lint",
    "postlint": "npm run format"
  },
  "devDependencies": {
    "@types/node": "^25.7.0",
    "esbuild": "^0.28.0",
    "oxlint": "^1.64.0",
    "oxlint-tsgolint": "^0.22.1",
    "prettier": "^3.8.3",
    "tap": "^21.7.2",
    "tshy": "^4.1.2",
    "typedoc": "^0.28.19"
  },
  "engines": {
    "node": ">=20"
  },
  "funding": {
    "url": "https://github.com/sponsors/isaacs"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/isaacs/glob-bin.git"
  },
  "type": "module",
  "tshy": {
    "selfLink": false,
    "dialects": [
      "esm"
    ],
    "exports": {
      "./package.json": "./package.json"
    }
  },
  "exports": {
    "./package.json": "./package.json"
  },
  "dependencies": {
    "foreground-child": "^4.0.0",
    "glob": "^13.0.0",
    "jackspeak": "^4.2.1",
    "package-json-from-dist": "^1.0.1"
  }
}

